# cheet.js [![Build Status](https://drone.io/github.com/namuol/cheet.js/status.png)](https://drone.io/github.com/namuol/cheet.js/latest) [![dependency Status](https://david-dm.org/namuol/cheet.js/status.svg?style=flat-square)](https://david-dm.org/namuol/cheet.js#info=devDependencies) [![devDependency Status](https://david-dm.org/namuol/cheet.js/dev-status.svg?style=flat-square)](https://david-dm.org/namuol/cheet.js#info=devDependencies)

## easy easter eggs in the browser

```javascript
cheet('↑ ↑ ↓ ↓ ← → ← → b a', function () { alert('Voilà!'); });
```

```javascript
cheet('i d d q d', function () {
  alert('god mode enabled');
});
```

```javascript
cheet('o n e a t a t i m e', {
  next: function (str, key, num, seq) {
    console.log('key pressed: ' + key);
    console.log('progress: ' + num / seq.length);
    console.log('seq: ' + seq.join(' '));
  },

  fail: function () {
    console.log('sequence failed');
  },

  done: function () {
    console.log('+30 lives ;)');
  }
});
```

```javascript
cheet('o n c e', function () {
  console.log('This will only fire once.');
  cheet.disable('o n c e');
});
```

```javascript
var sequences = {
  cross: 'up down left right',
  circle: 'left up right down'
};

cheet(sequences.cross);
cheet(sequences.circle);

cheet.done(function (seq) {
  if (seq === sequences.cross) {
    console.log('cross!');
  } else {
    console.log('circle!');
  }
});
```

### Demo

[My personal site](http://namuol.github.io) uses cheet.js (Try the [Konami Code](http://en.wikipedia.org/wiki/Konami_Code))

