[workspace.package]
version = "54.0.0"
homepage = "https://datafusion.apache.org/python"
repository = "https://github.com/apache/datafusion-python"
authors = ["Apache DataFusion <dev@datafusion.apache.org>"]
description = "Apache DataFusion DataFrame and SQL Query Engine"
readme = "README.md"
license = "Apache-2.0"
edition = "2024"
rust-version = "1.88"

[workspace]
members = ["crates/core", "crates/util", "examples/datafusion-ffi-example"]
resolver = "3"

[workspace.dependencies]
tokio = { version = "1.52" }
pyo3 = { version = "0.28" }
pyo3-async-runtimes = { version = "0.28" }
pyo3-log = "0.13.3"
chrono = { version = "0.4", default-features = false }
arrow = { version = "58" }
arrow-array = { version = "58" }
arrow-schema = { version = "58" }
arrow-select = { version = "58" }
datafusion = { version = "54" }
datafusion-substrait = { version = "54" }
datafusion-proto = { version = "54" }
datafusion-ffi = { version = "54" }
datafusion-catalog = { version = "54", default-features = false }
